package com.nova.backend.notification;
import com.nova.backend.mobile.MobileSessionAuthenticator; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/mobile/notifications") public class MobileNotificationController { private final NotificationRepository repo;private final MobileSessionAuthenticator auth;public MobileNotificationController(NotificationRepository repo,MobileSessionAuthenticator auth){this.repo=repo;this.auth=auth;}@GetMapping public List<NovaNotification> list(@RequestHeader(value="Authorization",required=false)String token){return repo.talent(auth.authenticate(token).contractorId());}@PostMapping("/{id}/read") public void read(@RequestHeader(value="Authorization",required=false)String token,@PathVariable UUID id){repo.readTalent(id,auth.authenticate(token).contractorId());}}
